 47 | void awts_draw_text(AwtsBrowserState* state, float x, float y, const char* text, float r, float g, float b) {
 48 |   if (!state->font.ready || !text) return;
 49 |   glColor3f(r, g, b);
 50 |   glRasterPos2f(x, y);
 51 |   glPushAttrib(GL_LIST_BIT);
 52 |   glListBase(state->font.base);
 53 |   glCallLists((GLsizei)strlen(text), GL_UNSIGNED_BYTE, text);
 54 |   glPopAttrib();
