126 | static int draw_executor_stream(AwtsBrowserState* state) {
127 |   const char* stream = AWTS_NATIVE_RENDER_STREAM;
128 |   if (!stream || !*stream) return 0;
129 |   char* copy = _strdup(stream);
130 |   if (!copy) return 0;
131 |   float ox = sx(state, 96), oy = sy(state, 150);
132 |   float scaleX = sw(state, 2), scaleY = -sh(state, 2);
133 |   for (char* line = copy; line && *line;) {
134 |     char* next = strchr(line, '\n');
135 |     if (next) *next++ = 0;
136 |     char kind[16], id[16], a[64], b[64], c[160], d[64], e[64];
137 |     char* at = line;
138 |     memset(kind, 0, sizeof(kind)); memset(id, 0, sizeof(id));
139 |     memset(a, 0, sizeof(a)); memset(b, 0, sizeof(b)); memset(c, 0, sizeof(c));
140 |     memset(d, 0, sizeof(d)); memset(e, 0, sizeof(e));
141 |     next_part(&at, kind, sizeof(kind)); next_part(&at, id, sizeof(id));
142 |     next_part(&at, a, sizeof(a)); next_part(&at, b, sizeof(b));
143 |     next_part(&at, c, sizeof(c)); next_part(&at, d, sizeof(d)); next_part(&at, e, sizeof(e));
144 |     if (!strcmp(kind, "BOX")) {
145 |       float r, g, blue; hex_color(e, &r, &g, &blue);
146 |       rect(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, r, g, blue);
147 |       outline(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, 0.70f, 0.72f, 0.78f);
148 |     } else if (!strcmp(kind, "TEXT")) {
149 |       float r, g, blue; hex_color(d, &r, &g, &blue);
150 |       awts_draw_text(state, ox + atof(a) * scaleX, oy + atof(b) * scaleY, c, r, g, blue);
151 |     } else if (!strcmp(kind, "WEBGL")) {
152 |       rect(sx(state, 470), sy(state, 180 + atoi(id) * 18), sw(state, 220), -sh(state, 10), 0.10f, 0.18f, 0.32f);
153 |     }
154 |     line = next;
155 |   }
156 |   free(copy);
157 |   return 1;
158 | }
